cd /tmp/py; osv-scanner -L requirements.txt --format json 2>/dev/null > out.json; python3 - <<'E'
import json
d=json.load(open('/tmp/py/out.json'))
for r in d['results']:
  for p in r['packages']:
    pk=p['package']
    if pk['name'] not in ('django','pillow','nltk','django-allauth','djangorestframework','bleach','filelock','pyopenssl','cryptography','python-dotenv','granian','h11','autobahn','tornado','twisted'): continue
    fixes=set()
    for v in p['vulnerabilities']:
      for a in v.get('affected',[]):
        if a['package']['name'].lower()!=pk['name']: continue
        for rg in a.get('ranges',[]):
          for e in rg['events']:
            if 'fixed' in e: fixes.add(e['fixed'])
    print(pk['name'],pk['version'],sorted(fixes,key=lambda s:[int(x) if x.isdigit() else 0 for x in s.replace('-','.').split('.')])[-3:])
E

